      ..._systemTools(),
      ..._workItemTools(),
      ..._workItemLinkTools(),
      ..._workItemQueryTools(),
      ..._commentTools(),
      ..._teamTools(),
      ..._projectTools(),
      ..._pullRequestTools(),
      ..._pullRequestUpdateTools(),
      ..._pullRequestStatusTools(),
      ..._repoTools(),
      ..._repoDetailTools(),
      ..._buildTools(),
