/// Field-mutation tools: `jira_update_field` / `jira_clear_field`.
List<ToolDefinition> _fieldTools() => [
      _jiraTool(
        name: 'jira_update_field',
        description: 'Update a single field on a Jira ticket',
        params: [
          _keyParam,
          _fieldUpdateParam,
